from collections import deque, defaultdict
R,C=len(grid),len(grid[0]); labels=[[-1]*C for _ in range(R)]; comps=[]
for i in range(R):
 for j in range(C):
  if grid[i][j]!=0 and labels[i][j]<0:
   q=deque([(i,j)]); labels[i][j]=len(comps); cells=[]
   while q:
    x,y=q.popleft();cells.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=x+dx,y+dy
     if 0<=a<R and 0<=b<C and grid[a][b]!=0 and labels[a][b]<0:
      labels[a][b]=labels[i][j];q.append((a,b))
   comps.append(cells)
seed_comps={v:labels[i][j] for i,row in enumerate(grid) for j,v in enumerate(row) if v in (4,8,6)}
seed_comps, [(k,len(comps[k]),(min(x for x,y in comps[k]),max(x for x,y in comps[k]),min(y for x,y in comps[k]),max(y for x,y in comps[k]))) for k in set(seed_comps.values())]

out=[row[:] for row in grid]
centers=defaultdict(list)
for i in range(R-2):
 for j in range(C-2):
  if all(grid[x][y]!=0 for x in range(i,i+3) for y in range(j,j+3)):
   comp=labels[i+1][j+1]
   if comp in seed_comps.values():
    color=next(v for v,k in seed_comps.items() if k==comp)
    centers[color].append((i+1,j+1));out[i+1][j+1]=color
